<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useCoffee} from '../stores/coffee';import {roleLabels,money,localTime,localDate,canEditEntity} from '../../../../packages/shared/src/domain';import type {Role} from '../../../../packages/shared/src/types';import type {Entity} from '../data/repository';import Modal from '../../../../packages/ui/src/Modal.vue';import Icon from '../components/Icon.vue';
const route=useRoute();const router=useRouter();const s=useCoffee();const key=computed(()=>String(route.meta.key));const editing=ref(false);const deleting=ref<any>();const form=ref<any>({});const query=ref('');const settings=ref({...s.state.settings});const selectedRole=ref<Role>('owner');
const banks=[{bin:'970436',name:'Vietcombank'},{bin:'970415',name:'VietinBank'},{bin:'970418',name:'BIDV'},{bin:'970422',name:'MB Bank'},{bin:'970407',name:'Techcombank'},{bin:'970416',name:'ACB'},{bin:'970432',name:'VPBank'},{bin:'970423',name:'TPBank'},{bin:'970403',name:'Sacombank'}];
const editable=computed(()=>canEditEntity(s.role,key.value));const entities=['categories','banks','branches','printers','staff'];const entity=computed(()=>key.value as Entity);
const rows=computed(()=>{const values=(s.state as any)[key.value] as any[];return (values??[]).filter(v=>(v.name??v.bankName??'').toLowerCase().includes(query.value.toLowerCase()))});
const labels:Record<string,string>={categories:'danh mục',banks:'tài khoản ngân hàng',branches:'cơ sở',printers:'máy in',staff:'nhân viên'};
const permissions=[{name:'Xem dashboard & báo cáo',roles:['owner','manager']},{name:'Sửa sản phẩm, ảnh, danh mục',roles:['owner','manager']},{name:'Sửa ngân hàng nhận tiền',roles:['owner']},{name:'Mở/chuyển/gộp bàn',roles:['owner','manager','cashier','waiter']},{name:'Tạo & xác nhận đơn',roles:['owner','manager','cashier','waiter']},{name:'Pha chế, đánh dấu sẵn sàng',roles:['owner','manager','barista']},{name:'Thu tiền & in bill',roles:['owner','manager','cashier']},{name:'Hoàn tiền / hủy sau pha chế',roles:['owner','manager']},{name:'Cấu hình máy in & nhân viên',roles:['owner','manager']}];
watch(key,()=>{editing.value=false;deleting.value=undefined;query.value='';settings.value={...s.state.settings}});
function edit(row?:any){form.value=row?JSON.parse(JSON.stringify(row)):{id:crypto.randomUUID(),active:true,branchId:s.branchId,name:'',bin:'970436',bankName:'Vietcombank',account:'',holder:'',address:'',phone:'',email:'',role:'waiter',branchIds:[s.branchId],transport:'usb',paper:'80',purpose:'cashier'};editing.value=true}
function save(){if(key.value==='banks')form.value.bankName=banks.find(b=>b.bin===form.value.bin)?.name??form.value.bin;if(key.value==='staff')form.value.branchIds=form.value.branchIds?.length?form.value.branchIds:[s.branchId];if(s.upsert(entity.value,form.value))editing.value=false}
function archive(){if(deleting.value&&s.archive(entity.value,deleting.value.id))deleting.value=undefined}
function saveSettings(){if(!s.canManage)return;s.run(()=>s.repo.saveSettings(settings.value))}
function role(){s.role=selectedRole.value;router.push(selectedRole.value==='barista'?'/kitchen':selectedRole.value==='waiter'?'/waiter':selectedRole.value==='platform'?'/platform':'/pos')}
function uploadLogo(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>500000){s.notify('Chọn logo PNG/JPEG/WebP dưới 500 KB.','error');return}const reader=new FileReader();reader.onload=()=>settings.value.logo=String(reader.result);reader.readAsDataURL(file)}
</script>
<template><div class="page"><template v-if="entities.includes(key)"><div class="page-heading"><div><h2>{{route.meta.title}}</h2><p>{{({categories:'Phân nhóm món để khách và nhân viên tìm nhanh.',banks:'Tài khoản nhận tiền cho VietQR, riêng theo từng cơ sở.',branches:'Thông tin và trạng thái của từng cơ sở.',printers:'Phân máy in thu ngân và pha chế theo cơ sở.',staff:'Gán vai trò và phạm vi cơ sở cho nhân viên.'} as Record<string,string>)[key]}}</p></div><button v-if="editable" class="btn primary" @click="edit()"><Icon name="plus"/>Thêm {{labels[key]}}</button></div><div class="filters"><label class="search-field"><Icon name="search"/><input v-model="query" :placeholder="'Tìm '+labels[key]+'...'" :aria-label="'Tìm '+labels[key]"></label></div><div class="panel table-scroll"><table class="data-table"><thead><tr><th>{{key==='banks'?'Ngân hàng':'Tên'}}</th><th v-if="key!=='categories'">{{key==='banks'?'Tài khoản nhận tiền':key==='branches'?'Địa chỉ':key==='staff'?'Vai trò':'Kết nối'}}</th><th v-if="!['categories','branches'].includes(key)">Cơ sở</th><th v-if="key!=='categories'">Trạng thái</th><th></th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.name??r.bankName}}</strong><small v-if="key==='banks'">{{r.holder}}</small><small v-if="key==='staff'">{{r.email||'Chưa có email'}}</small></td><td v-if="key!=='categories'"><template v-if="key==='banks'">{{r.account}}<small>BIN {{r.bin}}</small></template><template v-else-if="key==='branches'">{{r.address}}<small>{{r.phone}}</small></template><template v-else-if="key==='staff'">{{roleLabels[r.role]}}</template><template v-else>{{r.transport==='usb'?'USB Windows':'Wi-Fi / LAN'}} · {{r.paper}} mm<small>{{r.purpose==='bar'?'Quầy pha chế':'Thu ngân'}}</small></template></td><td v-if="!['categories','branches'].includes(key)">{{key==='staff'?r.branchIds.map((id:string)=>s.state.branches.find(b=>b.id===id)?.name).join(', '):s.state.branches.find(b=>b.id===r.branchId)?.name}}</td><td v-if="key!=='categories'"><span class="status" :class="r.active?'served':'cancelled'">{{key==='printers'?'Chưa kết nối Agent':r.active?'Đang sử dụng':'Ngừng sử dụng'}}</span></td><td><div class="row-actions"><button class="icon-button" :aria-label="'Sửa '+(r.name??r.bankName)" :disabled="!editable" @click="edit(r)"><Icon name="edit" :size="17"/></button><button class="icon-button" :aria-label="'Xóa '+(r.name??r.bankName)" :disabled="!editable" @click="deleting=r"><Icon name="trash" :size="17"/></button><button v-if="key==='printers'" class="btn small outline" @click="s.notify('Chưa kết nối Print Agent. Có thể dùng in từ trình duyệt ở màn hình bill.')">In thử</button></div></td></tr></tbody></table><div v-if="!rows.length" class="empty"><Icon :name="key==='banks'?'bank':key==='staff'?'staff':'layers'" :size="38"/><h3>Chưa có {{labels[key]}}</h3><p>{{key==='banks'?'Thêm tài khoản của cơ sở để tạo VietQR đúng ngân hàng và số tiền.':'Thêm dữ liệu để bắt đầu quản lý.'}}</p><button v-if="editable" class="btn primary" @click="edit()">Thêm {{labels[key]}}</button></div></div><p v-if="key==='banks'" class="muted small-copy">Thông tin ngân hàng lưu trên trình duyệt này. QR đã tạo giữ nguyên tài khoản và số tiền tại thời điểm tạo.</p><section v-if="key==='printers'" class="panel print-jobs"><div class="panel-heading"><h3>Hàng đợi in</h3><span>{{s.state.printJobs.filter(j=>j.branchId===s.branchId).length}} yêu cầu</span></div><div v-for="j in s.state.printJobs.filter(j=>j.branchId===s.branchId)" :key="j.id" class="list-row"><div><strong>{{s.state.orders.find(o=>o.id===j.orderId)?.number}}</strong><small>{{j.purpose==='bar'?'Phiếu pha chế':'Bill thu ngân'}} · {{localTime(j.createdAt)}}</small></div><span class="status pending">Chờ kết nối Agent</span><small>{{j.reason}}</small><button class="btn small outline" @click="s.notify('Chưa có Print Agent để gửi lại job. Trạng thái in được giữ nguyên.')">Thử lại</button></div><div v-if="!s.state.printJobs.some(j=>j.branchId===s.branchId)" class="empty"><Icon name="printer" :size="32"/><p>Chưa có yêu cầu in tự động.</p></div></section></template>
<template v-else-if="key==='settings'"><div class="page-heading"><div><h2>Cài đặt quán</h2><p>Thông tin hiển thị trên menu khách và bill.</p></div><button class="btn primary" @click="saveSettings" :disabled="!s.canManage">Lưu cài đặt</button></div><div class="settings-grid"><section class="panel settings-panel"><h3>Thông tin thương hiệu</h3><label class="field"><span>Tên quán</span><input v-model="settings.name" maxlength="100"></label><label class="field"><span>Địa chỉ</span><input v-model="settings.address" maxlength="200"></label><label class="field"><span>Số điện thoại</span><input v-model="settings.phone" maxlength="20"></label><label class="field"><span>Múi giờ</span><input value="Asia/Ho_Chi_Minh" disabled></label><p class="muted small-copy">Tiền tệ VND. Các khoản tiền được lưu bằng số nguyên.</p></section><section class="panel settings-panel"><h3>Logo & menu khách</h3><div class="logo-preview"><img v-if="settings.logo" :src="settings.logo" alt="Logo quán"><Icon v-else name="coffee" :size="52"/></div><label class="file-picker"><Icon name="image"/>Tải logo<input type="file" accept="image/png,image/jpeg,image/webp" @change="uploadLogo" aria-label="Tải logo quán"></label><button v-if="settings.logo" class="text-link" @click="settings.logo=''">Gỡ logo</button><label class="check-row"><input type="checkbox" v-model="settings.allowCalls">Cho khách gọi nhân viên</label><label class="check-row"><input type="checkbox" v-model="settings.allowPaymentRequests">Cho khách yêu cầu thanh toán</label><p class="muted small-copy">Thanh toán trực tuyến và gửi đơn offline chưa được bật.</p></section></div></template>
<template v-else-if="key==='permissions'"><div class="page-heading"><div><h2>Vai trò & phân quyền</h2><p>Quyền vận hành mặc định và phạm vi cơ sở được gán tại trang Nhân viên.</p></div><RouterLink class="btn primary" to="/admin/staff">Gán vai trò nhân viên</RouterLink></div><section class="panel table-scroll"><table class="data-table permission-table"><thead><tr><th>Thao tác</th><th v-for="r in ['owner','manager','cashier','waiter','barista']" :key="r">{{roleLabels[r]}}</th></tr></thead><tbody><tr v-for="p in permissions" :key="p.name"><td>{{p.name}}</td><td v-for="r in ['owner','manager','cashier','waiter','barista']" :key="r"><Icon v-if="p.roles.includes(r)" name="check"/><span v-else>—</span></td></tr></tbody></table></section><p class="muted small-copy">Đây là cấu hình giao diện để xem theo vai trò. Xác thực, RBAC và tenant isolation tại máy chủ sẽ được triển khai ở backend.</p></template>
<template v-else-if="key==='invoices'"><div class="page-heading"><div><h2>Hóa đơn điện tử</h2><p>Tách riêng khỏi bill bán hàng và bản in nhiệt.</p></div><span class="status pending">Chưa kết nối nhà cung cấp</span></div><div class="settings-grid"><section class="panel settings-panel"><h3>Kết nối nhà cung cấp</h3><label class="field"><span>Nhà cung cấp</span><select disabled><option>Chưa chọn nhà cung cấp</option></select></label><label class="field"><span>Mã số thuế</span><input placeholder="Cấu hình sau khi chọn nhà cung cấp" disabled></label><label class="field"><span>Thông tin API</span><input placeholder="Được lưu bảo mật trên máy chủ" disabled></label><button class="btn primary" disabled>Kết nối & kiểm tra</button></section><section class="panel empty"><Icon name="file" :size="42"/><h3>Chưa có hóa đơn đã phát hành</h3><p>Phát hành, tra cứu, điều chỉnh và thay thế sẽ hoạt động khi API nhà cung cấp được kết nối.</p><RouterLink to="/admin/receipts" class="btn outline">Xem bill bán hàng</RouterLink></section></div></template>
<template v-else-if="key==='subscription'"><div class="page-heading"><div><h2>Gói dịch vụ của quán</h2><p>Phạm vi tính năng và quản lý đăng ký SaaS.</p></div></div><section class="subscription-hero panel"><div><Icon name="package" :size="38"/><h3>Gói vận hành quán</h3><p>POS · QR ordering · Quản lý nhiều cơ sở</p><span class="status pending">Chưa kết nối quản lý thuê bao</span></div><div class="subscription-limits"><div><strong>{{s.state.branches.filter(b=>b.active).length}}</strong><span>Cơ sở đang xem</span></div><div><strong>{{s.state.staff.filter(u=>u.active).length}}</strong><span>Nhân viên</span></div><div><strong>16</strong><span>Nhóm giao diện</span></div></div></section><section class="panel settings-panel"><h3>Thanh toán gói & lịch sử</h3><p class="muted">Giá gói, hạn mức, kỳ thanh toán và trạng thái thuê bao sẽ lấy từ API SaaS. Chưa phát sinh khoản thanh toán dịch vụ.</p><button class="btn outline" disabled>Nâng cấp gói</button></section></template>
<template v-else-if="key==='audit'"><div class="page-heading"><div><h2>Nhật ký thay đổi</h2><p>Ghi nhận các thao tác đã lưu trên trình duyệt này.</p></div></div><section class="panel table-scroll"><table class="data-table"><thead><tr><th>Thời gian</th><th>Thao tác</th><th>Phạm vi</th></tr></thead><tbody><tr v-for="a in s.state.audit" :key="a.id"><td>{{localDate(a.at)}} {{localTime(a.at)}}</td><td>{{a.action}}</td><td>Trình duyệt hiện tại</td></tr></tbody></table><div v-if="!s.state.audit.length" class="empty"><Icon name="orders" :size="38"/><h3>Chưa có thao tác đã lưu</h3><p>Thay đổi sản phẩm, bàn hoặc đơn hàng sẽ xuất hiện ở đây.</p></div></section></template>
<template v-else-if="key==='platform'"><div class="page-heading"><div><h2>Super Admin SaaS</h2><p>Tổng quan quán, cơ sở và các module của nền tảng.</p></div><span class="status pending">Control plane chưa kết nối</span></div><div class="metric-grid"><article class="metric"><Icon name="store" :size="32"/><div><span>Không gian đang xem</span><strong>1 quán</strong></div></article><article class="metric"><Icon name="layers" :size="32"/><div><span>Cơ sở</span><strong>{{s.state.branches.length}}</strong></div></article><article class="metric"><Icon name="staff" :size="32"/><div><span>Nhân viên</span><strong>{{s.state.staff.length}}</strong></div></article></div><section class="panel"><div class="panel-heading"><h3>Quán trong không gian hiện tại</h3></div><div class="list-row platform-tenant"><div class="brand-mark"><Icon name="coffee"/></div><div><h3>{{s.state.settings.name}}</h3><p class="muted">{{s.state.branches.length}} cơ sở · {{s.state.products.filter(p=>p.active).length}} món</p></div><RouterLink class="btn primary" to="/admin/dashboard">Mở Admin quán</RouterLink></div></section><section class="panel settings-panel"><h3>Vòng đời tenant & thuê bao</h3><p class="muted">Tạo tenant, khóa/mở, provisioning, backup và quản lý thuê bao cần API platform có xác thực Super Admin. Các thao tác này chưa khả dụng.</p><div class="action-row"><button class="btn outline" disabled>Tạo tenant</button><button class="btn outline" disabled>Khóa tenant</button><RouterLink class="btn outline" to="/admin/subscription">Xem gói dịch vụ</RouterLink></div></section></template>
<template v-else-if="key==='login'"><section class="panel role-picker"><Icon name="coffee" :size="44"/><h2>Chọn giao diện theo vai trò</h2><p class="muted">Mở các màn hình để xem luồng vận hành. Chưa xác thực tài khoản máy chủ.</p><label class="field"><span>Vai trò</span><select v-model="selectedRole"><option v-for="(name,k) in roleLabels" :key="k" :value="k">{{name}}</option></select></label><button class="btn primary full" @click="role">Mở giao diện</button></section></template></div>
<Modal v-if="editing" :title="(rows.some(r=>r.id===form.id)?'Sửa ':'Thêm ')+labels[key]" @close="editing=false"><form @submit.prevent="save"><template v-if="key==='banks'"><label class="field"><span>Ngân hàng</span><select v-model="form.bin" aria-label="Ngân hàng nhận tiền"><option v-for="b in banks" :key="b.bin" :value="b.bin">{{b.name}} · {{b.bin}}</option></select></label><label class="field"><span>Số tài khoản</span><input required v-model="form.account" inputmode="numeric" pattern="[0-9]{6,19}" maxlength="19" aria-label="Số tài khoản"></label><label class="field"><span>Tên chủ tài khoản</span><input required v-model="form.holder" maxlength="80" aria-label="Tên chủ tài khoản"></label></template><template v-else><label class="field"><span>Tên {{labels[key]}}</span><input required v-model="form.name" maxlength="100" aria-label="Tên"></label></template><template v-if="key==='branches'"><label class="field"><span>Địa chỉ</span><input v-model="form.address" maxlength="200"></label><label class="field"><span>Điện thoại</span><input v-model="form.phone" maxlength="20"></label></template><template v-if="key==='staff'"><label class="field"><span>Email</span><input type="email" v-model="form.email"></label><label class="field"><span>Vai trò</span><select v-model="form.role"><option v-for="r in ['owner','manager','cashier','waiter','barista']" :key="r" :value="r">{{roleLabels[r]}}</option></select></label><h3>Cơ sở được phép</h3><label v-for="b in s.state.branches.filter(b=>b.active)" :key="b.id" class="check-row"><input type="checkbox" v-model="form.branchIds" :value="b.id">{{b.name}}</label><p class="muted small-copy">Chưa tạo tài khoản đăng nhập hoặc gửi email mời.</p></template><label v-if="['banks','printers'].includes(key)" class="field"><span>Cơ sở</span><select v-model="form.branchId"><option v-for="b in s.state.branches.filter(b=>b.active)" :key="b.id" :value="b.id">{{b.name}}</option></select></label><template v-if="key==='printers'"><div class="form-row"><label class="field"><span>Kết nối</span><select v-model="form.transport"><option value="usb">USB Windows</option><option value="lan">Wi-Fi / LAN</option></select></label><label class="field"><span>Khổ giấy</span><select v-model="form.paper"><option value="80">80 mm</option><option value="58">58 mm</option></select></label></div><label class="field"><span>{{form.transport==='lan'?'IP / cổng máy in':'Tên máy in Windows'}}</span><input v-model="form.address" :placeholder="form.transport==='lan'?'192.168.1.100:9100':'Tên trong Windows Printers'"></label><label class="field"><span>Loại phiếu</span><select v-model="form.purpose"><option value="cashier">Bill thu ngân</option><option value="bar">Phiếu pha chế</option></select></label><p class="muted small-copy">Đang lưu cấu hình; chưa kết nối hoặc gửi lệnh tới máy in thật.</p></template><label v-if="key!=='categories'" class="check-row"><input type="checkbox" v-model="form.active">Đang sử dụng</label><div class="modal-footer"><button type="button" class="btn outline" @click="editing=false">Hủy</button><button class="btn primary">Lưu {{labels[key]}}</button></div></form></Modal>
<Modal v-if="deleting" title="Ngừng sử dụng dữ liệu" @close="deleting=undefined"><p>{{deleting.name??deleting.bankName}} sẽ không còn dùng cho thao tác mới. Lịch sử giao dịch vẫn được giữ.</p><div class="modal-footer"><button class="btn outline" @click="deleting=undefined">Giữ lại</button><button class="btn danger" @click="archive">Xác nhận ngừng sử dụng</button></div></Modal></template>
